options.getOption:
const frame = context.panel.data.series[0];
const emptyOption = (message) => ({
  title: { text: message, left: 'center', top: 'middle' },
  xAxis: { type: 'value' },
  yAxis: { type: 'value', inverse: true },
  series: []
});
if (!frame) {
  return emptyOption('No heatmap data yet');
}
const field = (name) => frame.fields.find((f) => f.name === name);
const gridX = field('grid_x');
const gridY = field('grid_y');
const eventCount = field('event_count');
if (!gridX || !gridY || !eventCount) {
  return emptyOption('Missing heatmap fields');
}
const values = (f) => Array.from(f.values);
const xs = values(gridX);
const ys = values(gridY);
const counts = values(eventCount);
const points = xs.map((x, i) => [Number(x), Number(ys[i]), Number(counts[i])]);
const maxCount = Math.max(1, ...counts.map((v) => Number(v)));
return {
  tooltip: {
    position: 'top',
    formatter: (p) => `x: ${p.value[0]}<br/>y: ${p.value[1]}<br/>events: ${p.value[2]}`
  },
  grid: { left: 56, right: 40, top: 24, bottom: 48 },
  xAxis: { type: 'value', name: 'x bucket', minInterval: 100 },
  yAxis: { type: 'value', name: 'y bucket', minInterval: 100, inverse: true },
  visualMap: {
    min: 0,
    max: maxCount,
    calculable: true,
    orient: 'horizontal',
    left: 'center',
    bottom: 0,
    inRange: { color: ['#d7f0ff', '#6fb6ff', '#f7c948', '#f25f5c'] }
  },
  series: [{
    name: 'Mouse Events',
    type: 'heatmap',
    data: points,
    emphasis: { itemStyle: { borderColor: '#111827', borderWidth: 1 } }
  }]
};
